// Helper function to count lower-case letters with odd order in the alphabet
function CountLowerCaseOdd(txt: string) : int
    requires txt != null
    ensures 0 <= CountLowerCaseOdd(txt) <= |txt|
{
    var count := 0;
    var i := 0;
    while i < txt.Length
        invariant 0 <= count <= i && i <= txt.Length
    {
        if txt[i] >= 'a' && txt[i] <= 'z' && (ord(txt[i]) % 2 == 1) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

